{
  "description": "The creature is a quadrupedal hybrid shown in right-facing profile against a plain light background. It has the overall body shape, fur, head, legs, paws and short tail of a brown bear, but its back, neck, shoulders, hips and portions of its limbs are covered with a glossy dark brown to black segmented exoskeleton resembling that of a beetle. A single large curved black horn with serrations projects from the top of its head. The under-flank shows a band of lighter tan segmented plates with oval openings. The animal stands on four paws with visible claws.",
  "parts": [
    {
      "part": "head",
      "looks_like": "bear head with dense brown fur, lighter tan fur on the muzzle and around the eyes, a dark brown nose at the tip of the snout, small brown eyes and a slightly open mouth",
      "where": "at the front of the body, facing to the right"
    },
    {
      "part": "horns",
      "looks_like": "single large glossy black horn curving upward and forward to a sharp point, with several small pointed tooth-like projections along its inner concave edge",
      "where": "arising from the top center of the head between the ears"
    },
    {
      "part": "ears",
      "looks_like": "two small rounded ears covered in thick brown fur",
      "where": "on top of the head, one on each side of the base of the horn"
    },
    {
      "part": "legs",
      "looks_like": "four thick sturdy legs covered in brown fur, each partially encased in glossy dark segmented armor on the upper and lower sections",
      "where": "two front legs under the chest/shoulder and two hind legs under the hips, supporting the body"
    },
    {
      "part": "feet",
      "looks_like": "four broad furry paws with blunt dark claws protruding from the toes, brown fur with darker pads",
      "where": "at the bottom ends of the four legs in contact with the ground"
    },
    {
      "part": "tail",
      "looks_like": "small short tuft of brown fur",
      "where": "at the rear of the body above the hind legs"
    },
    {
      "part": "plates",
      "looks_like": "numerous overlapping glossy dark brown to black chitinous plates with visible ridges and reflections, forming a continuous dorsal covering from neck to rump and separate shield-like plates over the shoulders and hips and segmented bands around the lower legs; along the lower side is a band of lighter tan plates with a row of oval holes",
      "where": "covering the back, neck, sides, shoulders, hips and parts of all four legs, with the tan band along the mid-flank/belly"
    },
    {
      "part": "shell",
      "looks_like": "hard glossy carapace-like shell made of fused dark plates over the back",
      "where": "extending along the dorsal midline from behind the neck to the rump"
    }
  ],
  "attached_objects": [],
  "animals": [
    "bear",
    "beetle"
  ],
  "separate_bodies": 1,
  "heads": 1,
  "walking_legs": 4,
  "wings": 0,
  "extra_limb_pieces": 0,
  "tails": 1
}
